const WebSocket = require('ws');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const SOLIDITY_ROOT = '/opt/contracts';
const sessions = new Map();

const ROLES = {
  ADMIN: 'admin',
  AUDITOR: 'auditor',
  DEVELOPER: 'developer'
};

const ROLE_PERMISSIONS = {
  [ROLES.ADMIN]: ['read', 'write', 'deploy', 'list'],
  [ROLES.AUDITOR]: ['read', 'list'],
  [ROLES.DEVELOPER]: ['read', 'write', 'list']
};

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Derive a strong, salted password hash using scrypt.
function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64);
}

// Precompute per-user salts and scrypt hashes at startup.
function buildUser(password, role) {
  const salt = crypto.randomBytes(16);
  const hash = hashPassword(password, salt);
  return { salt, hash, role };
}

const USERS = {
  'admin': buildUser('admin_pass_2024', ROLES.ADMIN),
  'auditor1': buildUser('audit_pass_2024', ROLES.AUDITOR),
  'dev1': buildUser('dev_pass_2024', ROLES.DEVELOPER)
};

function authenticate(username, password) {
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  const user = USERS[username];
  if (!user) return null;
  const inputHash = hashPassword(password, user.salt);
  if (inputHash.length === user.hash.length &&
      crypto.timingSafeEqual(inputHash, user.hash)) {
    return { username, role: user.role };
  }
  return null;
}

function hasPermission(role, action) {
  const perms = ROLE_PERMISSIONS[role];
  return perms && perms.includes(action);
}

function normalizeSolidityPath(userPath) {
  // Remove null bytes
  let cleaned = userPath.replace(/\0/g, '');

  // Normalize unicode to NFC form
  cleaned = cleaned.normalize('NFC');

  // Resolve the path relative to root
  const resolved = path.resolve(SOLIDITY_ROOT, cleaned);

  return resolved;
}

function isPathSafe(resolvedPath) {
  // Ensure the resolved path starts with our root
  const normalizedRoot = path.normalize(SOLIDITY_ROOT);
  return resolvedPath.startsWith(normalizedRoot + path.sep) || resolvedPath === normalizedRoot;
}

function validateSolidityFile(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  return ext === '.sol' || ext === '.json';
}

function handleReadContract(session, payload) {
  if (!hasPermission(session.role, 'read')) {
    return { error: 'Permission denied', code: 403 };
  }

  const { contractPath } = payload;
  if (!contractPath || typeof contractPath !== 'string') {
    return { error: 'Invalid contract path', code: 400 };
  }

  // Apply path normalization
  const resolved = normalizeSolidityPath(contractPath);

  // Security check: ensure path is within allowed directory
  if (!isPathSafe(resolved)) {
    return { error: 'Access denied: path outside contract directory', code: 403 };
  }

  // Validate file extension
  if (!validateSolidityFile(resolved)) {
    return { error: 'Only .sol and .json files allowed', code: 400 };
  }

  try {
    const content = fs.readFileSync(resolved, 'utf8');
    return { success: true, content, path: contractPath };
  } catch (e) {
    return { error: 'File not found', code: 404 };
  }
}

function handleListContracts(session, payload) {
  if (!hasPermission(session.role, 'list')) {
    return { error: 'Permission denied', code: 403 };
  }

  const { directory } = payload;
  const subDir = directory || '';
  const resolved = normalizeSolidityPath(subDir);

  if (!isPathSafe(resolved)) {
    return { error: 'Access denied', code: 403 };
  }

  try {
    const files = fs.readdirSync(resolved);
    return { success: true, files: files.filter(f => f.endsWith('.sol') || f.endsWith('.json')) };
  } catch (e) {
    return { error: 'Directory not found', code: 404 };
  }
}

function handleWriteContract(session, payload) {
  if (!hasPermission(session.role, 'write')) {
    return { error: 'Permission denied', code: 403 };
  }

  const { contractPath, content } = payload;
  if (!contractPath || typeof contractPath !== 'string' || !content) {
    return { error: 'Invalid parameters', code: 400 };
  }

  const resolved = normalizeSolidityPath(contractPath);

  if (!isPathSafe(resolved)) {
    return { error: 'Access denied: path outside contract directory', code: 403 };
  }

  if (!validateSolidityFile(resolved)) {
    return { error: 'Only .sol and .json files allowed', code: 400 };
  }

  try {
    fs.writeFileSync(resolved, content, 'utf8');
    return { success: true, message: 'Contract saved' };
  } catch (e) {
    return { error: 'Write failed', code: 500 };
  }
}

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  let session = null;

  ws.on('message', (data) => {
    let msg;
    try {
      msg = JSON.parse(data);
    } catch (e) {
      ws.send(JSON.stringify({ error: 'Invalid JSON' }));
      return;
    }

    if (msg.action === 'login') {
      const user = authenticate(msg.username, msg.password);
      if (user) {
        const token = generateToken();
        session = { ...user, token };
        sessions.set(token, session);
        ws.send(JSON.stringify({ success: true, token, role: user.role }));
      } else {
        ws.send(JSON.stringify({ error: 'Authentication failed' }));
      }
      return;
    }

    // All other actions require authentication
    if (!session) {
      ws.send(JSON.stringify({ error: 'Not authenticated', code: 401 }));
      return;
    }

    let result;
    switch (msg.action) {
      case 'read':
        result = handleReadContract(session, msg.payload || {});
        break;
      case 'list':
        result = handleListContracts(session, msg.payload || {});
        break;
      case 'write':
        result = handleWriteContract(session, msg.payload || {});
        break;
      default:
        result = { error: 'Unknown action', code: 400 };
    }

    ws.send(JSON.stringify(result));
  });

  ws.on('close', () => {
    if (session) {
      sessions.delete(session.token);
    }
  });
});

